import java.io.*;

public class Main {
    // starts = {car 1 start, car 2 start}; return {names in car 1, names in car 2} in input order
    static List<List<String>> carpool(String[] from, String[] to, long[] minutes, String[] starts, String[] names, String[] homes) {
