        List<List<String>> res = new ArrayList<>();
        res.add(new ArrayList<>());
        res.add(new ArrayList<>());
        return res;
    }

    public static void main(String[] args) throws IOException {
        String[] t = new String(System.in.readAllBytes()).trim().split("\\s+");
        int m = Integer.parseInt(t[0]);
        String[] from = new String[m], to = new String[m];
        long[] minutes = new long[m];
        for (int i = 0; i < m; i++) {
            from[i] = t[1 + 3 * i];
            to[i] = t[2 + 3 * i];
            minutes[i] = Long.parseLong(t[3 + 3 * i]);
        }
        int pos = 1 + 3 * m;
        String[] starts = {t[pos], t[pos + 1]};
        int p = Integer.parseInt(t[pos + 2]);
        String[] names = new String[p], homes = new String[p];
        for (int i = 0; i < p; i++) {
            names[i] = t[pos + 3 + 2 * i];
            homes[i] = t[pos + 4 + 2 * i];
        }
        List<List<String>> res = carpool(from, to, minutes, starts, names, homes);
        StringBuilder sb = new StringBuilder();
        for (int c = 0; c < 2; c++) {
            sb.append(res.get(c).isEmpty() ? "-" : String.join(" ", res.get(c))).append("\n");
        }
        System.out.print(sb);
    }
}
